import {
  Controller,
  Get,
  Req,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { ApiOperation, ApiResponse } from '@nestjs/swagger';
import axios from 'axios';

import { Request } from 'express';
import { AuthService } from './auth.service';

interface Claim {
  typ: string;
  val: string | Array<string>;
}

interface DecodedPrincipal {
  authType: string;
  claims: Array<Claim>;
}

interface AuthRefreshResponse {
  [key: string]: unknown;
}

@Controller('auth')
export class AuthController {
  private readonly cookie = 'cookie';

  public constructor(private readonly authService: AuthService) {} // <-- Proper injection

  @Get('claims')
  public getUserClaims(@Req() request: Request): DecodedPrincipal | undefined {
    return this.authService.getUserClaims(request); // <- call the service method here
  }

  @Get('refresh-token')
  public async refreshToken(
    @Req() request: Request,
  ): Promise<AuthRefreshResponse> {
    const cookie = request.headers[this.cookie];
    if (!cookie) {
      throw new HttpException(
        'No cookie found in request',
        HttpStatus.BAD_REQUEST,
      );
    }

    try {
      const response = await axios.get<AuthRefreshResponse>(
        'https://mesx-dev.app.corp/.auth/refresh',
        {
          headers: {
            cookie, // Pass the full cookie header as is
          },
        },
      );

      return response.data;
    } catch (error) {
      Logger.error(
        'Failed to invoke /.auth/refresh',
        error.response?.data ?? error.message,
      );
      throw new HttpException(
        'Token refresh failed',
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }

  @Get('user-plant')
  @ApiOperation({ summary: 'Get the list of plant IDs assigned to the user' })
  @ApiResponse({
    status: 200,
    description: 'List of plant IDs as strings',
    schema: {
      type: 'array',
      items: { type: 'string', example: '1146' },
    },
  })
  @ApiResponse({ status: 500, description: 'Internal server error' })
  public async resolveUserPlants(
    @Req() request: Request,
  ): Promise<Array<string>> {
    return this.authService.resolveUserPlants(request);
  }
}

