import { Injectable, Logger } from '@nestjs/common';
import { Request } from 'express';
import { AppConfigService } from 'src/config/app-config/app-config.service';
import { PlantService } from 'src/plant/plant.service';

interface Claim {
  typ: string;
  val: string | Array<string>;
}

interface DecodedPrincipal {
  authType: string;
  claims: Array<Claim>;
}

@Injectable()
export class AuthService {
  public static format(decoded: DecodedPrincipal): DecodedPrincipal {
    const claims: Array<Claim> = [];

    for (const [key, value] of Object.entries(decoded)) {
      let typ: string;

      // 🔒 strict mappings, no claimMappings map
      switch (key) {
        case 'sub': {
          typ =
            'http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier';
          break;
        }
        case 'given_name': {
          typ =
            'http://schemas.xmlsoap.org/ws/2005/05/identity/claims/givenname';
          break;
        }
        case 'family_name': {
          typ = 'http://schemas.xmlsoap.org/ws/2005/05/identity/claims/surname';
          break;
        }
        case 'email': {
          typ =
            'http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress';
          break;
        }
        case 'auth_time': {
          typ =
            'http://schemas.microsoft.com/ws/2008/06/identity/claims/authenticationinstant';
          break;
        }
        default: {
          typ = key;
        }
      }

      if (Array.isArray(value)) {
        for (const v of value) claims.push({ typ, val: String(v) });
      } else {
        claims.push({ typ, val: String(value) });
      }
    }

    // Add a nonce if not present
    if (!claims.some((c) => c.typ === 'nonce')) {
      claims.push({
        typ: 'nonce',
        val: 'ad6434610eee472fa95938c56f2a4746_20250820105358',
      });
    }

    return {
      authType: 'pingFederate',
      claims,
    };
  }

  private static normalizeRole(role: string): string {
    if (!role) return '';

    const regex = /CN=([^,]+)/;
    const match = regex.exec(role);

    return match ? match[1].trim() : role.trim();
  }

  private static extractFromClaims(principal: DecodedPrincipal): {
    roles: Array<string>;
    assignedPlants: Array<string>;
  } {
    const { claims } = principal;

    const roles =
      claims
        .filter(
          (c) => c.typ.toLowerCase().includes('groups') || c.typ === 'groups',
        )
        .flatMap((c) => (Array.isArray(c.val) ? c.val : [c.val])) ?? [];

    const assignedPlants = claims
      .filter((c) => c.typ === 'assignedPlants')
      .flatMap((c) => (Array.isArray(c.val) ? c.val : [c.val]));

    return { roles, assignedPlants };
  }

  private readonly logger = new Logger(AuthService.name);

  private readonly encodedClaimsHeaderName = 'x-ms-client-principal';

  public constructor(
    private readonly plantService: PlantService,
    private readonly appConfigService: AppConfigService,
  ) {}

  private capitalize(value: string): string {
    try {
      if (!value) return '';
      return value.charAt(0).toUpperCase() + value.slice(1).toLowerCase();
    } catch (error) {
      this.logger.error('Error in capitalize:', error);
      return '';
    }
  }

  public getUserClaims(request: Request): DecodedPrincipal | undefined {
    const encodedPrincipal = request.headers[
      this.encodedClaimsHeaderName
    ] as string;

    let decodedPrincipal: DecodedPrincipal | undefined;

    // === 1. Try to decode from base64 header ===
    if (encodedPrincipal) {
      try {
        const decoded = Buffer.from(encodedPrincipal, 'base64').toString(
          'utf8',
        );
        decodedPrincipal = JSON.parse(decoded) as DecodedPrincipal;
        const formatted = AuthService.format(decodedPrincipal);

        return formatted;
      } catch (error) {
        this.logger.warn(
          `Invalid base64 or JSON in ${this.encodedClaimsHeaderName}: ${error}`,
        );
      }
    }
    // === 2. Fallback to forwarded headers ===
    const fallbackPrincipal = this.buildFromForwardedHeaders(request);

    // === 3. Merge if both exist ===

    return decodedPrincipal ?? fallbackPrincipal;
  }

  private buildFromForwardedHeaders(
    request: Request,
  ): DecodedPrincipal | undefined {
    const email = request.headers['x-forwarded-email'] as string | undefined;
    const user = request.headers['x-forwarded-user'] as string | undefined;
    const groupsHeader = request.headers['x-forwarded-groups'] as
      | string
      | undefined;

    const identifier = user ?? email;
    if (!identifier) {
      this.logger.warn('No fallback identifier from proxy headers');
      return undefined;
    }

    const [givenName, surname] = this.extractNamesFromEmail(identifier);

    const claims: Array<Claim> = [
      {
        typ: 'http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier',
        val: identifier,
      },
    ];

    if (email) {
      claims.push({
        typ: 'http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress',
        val: email,
      });
    }

    if (givenName) {
      claims.push({
        typ: 'http://schemas.xmlsoap.org/ws/2005/05/identity/claims/givenname',
        val: givenName,
      });
    }

    if (surname) {
      claims.push({
        typ: 'http://schemas.xmlsoap.org/ws/2005/05/identity/claims/surname',
        val: surname,
      });
    }

    if (groupsHeader) {
      const groups = groupsHeader.includes(',')
        ? groupsHeader.split(',').map((g) => g.trim())
        : groupsHeader;
      claims.push({ typ: 'groups', val: groups });
    }

    return {
      authType: 'proxy-headers',
      claims,
    };
  }

  private extractNamesFromEmail(email: string): [string, string] {
    const [localPart] = email.split('@');
    const parts = localPart.split('.');
    const givenName = this.capitalize(parts[0]);
    const surname = parts[1] ? parts[1].toUpperCase() : '';
    return [givenName, surname];
  }

  public async resolveUserPlants(request: Request): Promise<Array<string>> {
    try {
      const principal = this.getUserClaims(request);

      if (!principal) {
        throw new Error('No claims found for user');
      }

      const { roles, assignedPlants } =
        AuthService.extractFromClaims(principal);

      const cleanedRoles = roles.map((r) => AuthService.normalizeRole(r));

      // Get exception roles from Azure App Configuration
      const exceptionRolesValue =
        await this.appConfigService.getConfigurationValue(
          'AUTH_PROXY_EXCEPTION_ROLES',
        );
      this.logger.log('exceptionRolesValue:', exceptionRolesValue);

      const exceptionRoles = Array.isArray(exceptionRolesValue)
        ? exceptionRolesValue.map((r) => r.trim())
        : (exceptionRolesValue?.split(';').map((r) => r.trim()) ?? []);

      const isExceptionUser = cleanedRoles.some((r) =>
        exceptionRoles.includes(r),
      );

      if (isExceptionUser) {
        // Exception roles get all plants
        return this.plantService.getPlant();
      }

      return assignedPlants;
    } catch (error) {
      this.logger.error('Error resolving user plants:', error);
      throw new Error('Failed to resolve user plants');
    }
  }
}

