async function bootstrap(): Promise<void> {
  const app = await NestFactory.create(AppModule);
  app.useGlobalPipes(new ValidationPipe());
  app.enableCors({
    allowedHeaders: 'Content-Type,Authorization',
    origin: '*',
  });
  const config = new DocumentBuilder()
    .setTitle('Backend UME Swagger Documentation')
    .setDescription(
      "In this page you'll find all of the necessary informations about the microservice Backend UME and it's different endpoints.",
    )
    .setVersion('1.0')
    .addServer('https://mesx-ppr.app.corp/ume-be/', 'pre-production')

    .build();
  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api', app, document);
  await app.listen(3000);
}
