import {
  Injectable,
  Logger,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { DaprClient, HttpMethod } from 'dapr-client';
import { DaprConfigService } from '../config/dapr/dapr-config.service';
import { AppListDTO } from './dto/app-list.dto';

@Injectable()
export class MenuService {
  private readonly daprClient: DaprClient;

  private readonly logger = new Logger(MenuService.name);

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.daprClient = new DaprClient();
  }

  public async fetchAppList(): Promise<Array<AppListDTO>> {
    const serviceAppId = this.daprConfigService.umeApiAppId;
    const serviceMethod = 'menus';

    try {
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
      );

      if (Array.isArray(response)) {
        return response.map((item) => new AppListDTO(item));
      }
      throw new NotFoundException(
        'Expected an array of app lists but received something else.',
      );
    } catch (error) {
      this.logger.error(
        'Failed to fetch App List from Dapr service',
        error.stack,
      );

      if (error.response) {
        throw new InternalServerErrorException(
          `Error communicating with Dapr service: ${error.response}`,
        );
      }

      if (error.code === 'ECONNREFUSED' || error.code === 'ETIMEOUT') {
        throw new InternalServerErrorException(
          'Network error or Dapr service unavailable.',
        );
      }

      throw new InternalServerErrorException(
        'An unexpected error occurred while fetching the app list.',
      );
    }
  }
}

