    plant: number,
    userId: number | string,
    appName: string,
  ): Promise<Array<UserPreferenceDto>> {
    try {
      const safeAppName = encodeURIComponent(appName);

      const token = process.env.TOKEN;
      const options = token
        ? {
            headers: {
              [this.authorizationHeaderKey]: `Bearer ${token}`,
            },
          }
        : undefined;

      const response = await this.daprClient.invoker.invoke(
        this.serviceAppId,
        `user-preference/${plant}/${userId}/${safeAppName}`,
        HttpMethod.GET,
        undefined,
        options,
      );

      return Array.isArray(response)
        ? (response as Array<UserPreferenceDto>)
        : [];
    } catch (error) {
      this.logger.error('Error fetching user preferences:', error);
      return [];
    }
  }

